package com.healthcare.portal.service;
import com.healthcare.portal.entity.*; import com.healthcare.portal.exception.*; import com.healthcare.portal.repository.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.security.SecureRandom; import java.time.LocalDateTime; import java.util.UUID;
@Service public class AccountRecoveryService { private final UserRepository users; private final PasswordResetTokenRepository resets; private final EmailOtpRepository otps; private final PasswordEncoder encoder; private final EmailService email; public AccountRecoveryService(UserRepository u,PasswordResetTokenRepository r,EmailOtpRepository o,PasswordEncoder e,EmailService m){users=u;resets=r;otps=o;encoder=e;email=m;} @Transactional public void requestReset(String emailAddress){users.findByEmail(emailAddress).ifPresent(u->{String token=UUID.randomUUID().toString(); resets.save(new PasswordResetToken(token,u,LocalDateTime.now().plusMinutes(30))); email.reset(u.getEmail(),token);});} @Transactional public void reset(String token,String password){PasswordResetToken t=resets.findByToken(token).orElseThrow(()->new BadRequestException("Invalid reset token")); if(t.getExpiresAt().isBefore(LocalDateTime.now())) throw new BadRequestException("Reset token expired"); User u=t.getUser();u.setPassword(encoder.encode(password));u.setForcePasswordChange(false);users.save(u);resets.delete(t);} @Transactional public void sendOtp(String emailAddress){User u=users.findByEmail(emailAddress).orElseThrow(()->new BadRequestException("User not found")); String otp=String.format("%06d",new SecureRandom().nextInt(1000000)); otps.save(new EmailOtp(u,otp,LocalDateTime.now().plusMinutes(10))); email.otp(u.getEmail(),otp);} @Transactional public void verifyOtp(String emailAddress,String otp){User u=users.findByEmail(emailAddress).orElseThrow(()->new BadRequestException("User not found")); EmailOtp o=otps.findTopByUserIdAndUsedFalseOrderByIdDesc(u.getId()).orElseThrow(()->new BadRequestException("OTP not found")); if(o.getExpiresAt().isBefore(LocalDateTime.now())||!o.getOtp().equals(otp)) throw new BadRequestException("Invalid or expired OTP");o.setUsed(true);otps.save(o);u.setEmailVerified(true);users.save(u);} }